        "tests/test_msae_independent_measurement_v3_post_m4_gen3.py",
        "tests/test_msae_measurement_remediation_v1.py",
        "configs/msae_independent_measurement_v1/protocol.json",
        "configs/msae_independent_measurement_v3/protocol.json",
        "configs/msae_independent_measurement_v3/authorization_commitment.json",
        "configs/msae_independent_measurement_v3/ed25519_public.pem",
        "configs/msae_independent_measurement_v3_post_m2_gen2/protocol.json",
        "configs/msae_independent_measurement_v3_post_m2_gen2/authorization_commitment.json",
        "configs/msae_independent_measurement_v3_post_m2_gen2/ed25519_public.pem",
        "configs/msae_independent_measurement_v3_post_m2_gen2/cpu_no_model_public_entry_trace.json",
        "configs/msae_independent_measurement_v3_post_m2_gen4/protocol.json",
